/*
 * A292777  First differences of A100290.
 * https://oeis.org/A292777
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A100290(n+1) - A100290(n); A100290 is generated by a
 *            sieve-like scan over k >= 1 keeping k with (2^popcount(k) - 1) |
 *            k, cached across calls
 * Range:     u8 n <= 2143, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Validated: standard, pass, 79 terms through n = 8387 (2026-11-08)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stddef.h>

static uint64_t *A100290_terms = NULL;
static size_t A100290_cnt = 0;
static size_t A100290_cap = 0;
static uint64_t A100290_cur = 0;   /* last candidate examined */

static unsigned A100290_pop(uint64_t x)
{
    unsigned k = 0;
    while (x) { x &= x - 1; k++; }
    return k;
}

static void A100290_extend(size_t need)
{
    while (A100290_cnt < need) {
        uint64_t c = ++A100290_cur;
        unsigned k = A100290_pop(c);
        uint64_t s = (k >= 64) ? ~(uint64_t)0 : (((uint64_t)1 << k) - 1);
        if (c % s == 0) {
            if (A100290_cnt == A100290_cap) {
                size_t nc = A100290_cap ? A100290_cap * 2 : 1024;
                uint64_t *p = (uint64_t *)realloc(A100290_terms, nc * sizeof(uint64_t));
                if (!p) return;
                A100290_terms = p;
                A100290_cap = nc;
            }
            A100290_terms[A100290_cnt++] = c;
        }
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;
    A100290_extend((size_t)n + 1);
    if (A100290_cnt < (size_t)n + 1) return (seq_t)0;
    uint64_t d = A100290_terms[n] - A100290_terms[n - 1];
    return (seq_t)d;
}
